import { Plugin } from "@opencode/plugin"
import { listEdgeVoices, synthesizeEdge } from "./edge.js"
import { VoiceRpc } from "./rpc.js"
import { WhisperEngine } from "./whisper/server.js"
import { installWhisperCpp, WhisperCppEngine, installFfmpeg } from "./whispercpp/server.js"

/**
 * Server part of the plugin.
 *
 * It registers the Edge TTS, WhisperX and whisper.cpp RPCs. Running them here
 * (instead of in the Electron main process) lets their dependencies resolve
 * from the plugin's own node_modules.
 */
export default Plugin.define({
  id: "voice-dictation",
  async setup(ctx) {
    const whisper = new WhisperEngine()
    const whisperCpp = new WhisperCppEngine()

    await ctx.rpc.register(VoiceRpc, {
      capabilities: async () => ({
        platform: process.platform,
        engines:
          process.platform === "linux"
            ? ["whispercpp"]
            : process.platform === "win32"
              ? ["windows", "system", "whisper"]
              : [],
      }),
      edgeVoices: async () => listEdgeVoices(),
      edgeSpeak: async (input) => {
        const { text, voice, rate } = input as { text: string; voice: string; rate: number }
        return synthesizeEdge({ text, voice, rate })
      },
      whisperTranscribe: async (input) => {
        return whisper.transcribe(input as {
          audio: string
          mime: string
          language: string
          python: string
          model: string
        })
      },
      whisperStatus: async (input) => {
        const { python, model } = input as { python: string; model: string }
        try {
          return await whisper.warm(python, model)
        } catch (cause) {
          return {
            ...whisper.statusOf(),
            ready: false,
            error: cause instanceof Error ? cause.message : String(cause),
          }
        }
      },
      whisperCppInstall: async (input) => {
        const { model } = input as { model: string }
        return installWhisperCpp(model)
      },
      whisperCppStatus: async (input) => {
        const { model } = input as { model: string }
        return whisperCpp.status(model)
      },
      whisperCppInstallFfmpeg: async () => installFfmpeg(),
      whisperCppTranscribe: async (input) => {
        return whisperCpp.transcribe(input as {
          audio: string
          mime: string
          language: string
          model: string
        })
      },
    })

    return () => {
      whisper.stop()
      whisperCpp.stop()
    }
  },
})

import type { Plugin } from "@opencode/plugin/gui"
import { Dictation, Speech, VoiceTyping } from "./contract"
import { diagnose, startEngine, type EngineHandle } from "./engines/system-speech"
import { listSapiVoices, speakSapi, type SpeakHandle } from "../sapi-speech"
import { sendVoiceTypingShortcut } from "../win-h"

type Status = "idle" | "starting" | "listening" | "error"

/**
 * Runs once in the Electron main process.
 *
 * One dictation runs at a time (there is one microphone); the window that
 * starts it receives the transcript events.
 */
export const main: Plugin.MainSetup = (ctx) => {
  let status: Status = "idle"
  let error = ""
  let locale = ""
  let handle: EngineHandle | undefined
  let stopping = false

  const reset = () => {
    handle = undefined
    stopping = false
  }

  const dictation = ctx.provide(Dictation, {
    state: () => ({ status, error, locale }),

    start(input, caller) {
      if (handle) {
        stopping = true
        handle.stop()
        reset()
      }

      status = "starting"
      error = ""
      locale = input.locale
      dictation.changed()

      const target = caller.window

      try {
        handle = startEngine(
          { locale: input.locale, minConfidence: input.minConfidence },
          {
            onReady(selected) {
              status = "listening"
              locale = selected
              dictation.changed()
            },
            onFinal(text, confidence) {
              dictation.emit("final", { text, confidence }, target)
            },
            onError(code, detail, available) {
              status = "error"
              error = code
              dictation.changed()
              dictation.emit("error", { code, detail, available }, target)
            },
            onExit(code, detail) {
              if (stopping) {
                reset()
                status = "idle"
                error = ""
                locale = ""
                dictation.changed()
                return
              }

              reset()
              if (status !== "error") {
                status = "error"
                error = code === null ? "ENGINE_EXIT" : `ENGINE_EXIT_${code}`
                dictation.changed()
                dictation.emit(
                  "error",
                  { code: "ENGINE_EXIT", detail: detail || (code === null ? "" : String(code)), available: [] },
                  target,
                )
              }
            },
          },
        )
      } catch (cause) {
        status = "error"
        error = "ENGINE_START_FAILED"
        dictation.changed()
        throw cause
      }
    },

    stop() {
      if (handle) {
        stopping = true
        handle.stop()
        reset()
      }
      status = "idle"
      error = ""
      locale = ""
      dictation.changed()
    },

    diagnose() {
      return diagnose()
    },
  })

  let talking: SpeakHandle | undefined

  const speech = ctx.provide(Speech, {
    speak(input) {
      talking?.stop()
      talking = speakSapi(input, (ok) => {
        talking = undefined
        speech.emit("done", { ok })
      })
    },

    stop() {
      if (talking) {
        talking.stop()
        talking = undefined
      }
    },

    voices() {
      return listSapiVoices()
    },
  })

  ctx.provide(VoiceTyping, {
    toggle() {
      return sendVoiceTypingShortcut()
    },
  })

  ctx.onCleanup(() => {
    if (handle) {
      stopping = true
      handle.stop()
      reset()
    }
    talking?.stop()
    talking = undefined
  })
}

import { spawn, type ChildProcess } from "node:child_process"
import { randomUUID } from "node:crypto"
import { mkdirSync, rmSync, writeFileSync } from "node:fs"
import { tmpdir } from "node:os"
import { dirname, join } from "node:path"
import { fileURLToPath } from "node:url"

const DEFAULT_PYTHON = "~/peopleby/voice_to_text/api_voice/demo/whisperx-env/bin/python"

export interface WhisperInput {
  audio: string
  mime: string
  language: string
  python: string
  model: string
}

export interface WhisperResult {
  text: string
  language: string
}

export interface WhisperStatus {
  ready: boolean
  model: string
  device: string
  error: string
}

function workerPath(): string {
  return join(dirname(fileURLToPath(import.meta.url)), "worker.py")
}

/** Converts a Windows path to the WSL mount path, e.g. C:\a\b -> /mnt/c/a/b. */
function toWslPath(path: string): string {
  if (process.platform !== "win32") return path

  return path
    .replace(/^([A-Za-z]):[\\/]/, (_, drive: string) => `/mnt/${drive.toLowerCase()}/`)
    .replace(/\\/g, "/")
}

function spawnWorker(python: string, model: string): ChildProcess {
  const env = { ...process.env, WHISPER_MODEL: model, WHISPER_DEVICE: "cuda" }

  // Inside `bash -lc`, a quoted `~` does not expand. Use $HOME instead.
  const pythonArg = python.startsWith("~/") ? `"$HOME/${python.slice(2)}"` : `"${python}"`
  const command = `${pythonArg} "${toWslPath(workerPath())}"`

  if (process.platform === "win32") {
    return spawn("wsl.exe", ["-d", "Ubuntu-22.04", "-e", "bash", "-lc", command], {
      env,
      stdio: ["pipe", "pipe", "pipe"],
      windowsHide: true,
    })
  }

  return spawn("bash", ["-lc", command], {
    env,
    stdio: ["pipe", "pipe", "pipe"],
  })
}

interface Waiter {
  resolve: (value: WhisperResult) => void
  reject: (error: Error) => void
  timer: NodeJS.Timeout
}

export class WhisperEngine {
  private child: ChildProcess | undefined
  private readyPromise: Promise<void> | undefined
  private readyResolve: (() => void) | undefined
  private readyReject: ((error: Error) => void) | undefined
  private buffer = ""
  private stderr = ""
  private waiters = new Map<string, Waiter>()
  private status: WhisperStatus = {
    ready: false,
    model: "",
    device: "cuda",
    error: "",
  }
  private python = ""
  private model = ""

  private start(python: string, model: string): Promise<void> {
    this.stop()
    this.python = python || DEFAULT_PYTHON
    this.model = model || "large-v3-turbo"
    this.status = { ready: false, model: this.model, device: "cuda", error: "" }
    this.stderr = ""

    const child = spawnWorker(this.python, this.model)
    this.child = child

    this.readyPromise = new Promise<void>((resolve, reject) => {
      this.readyResolve = resolve
      this.readyReject = reject
    })

    const timer = setTimeout(() => {
      this.status.error = "Whisper took too long to load the model"
      this.readyReject?.(new Error(this.status.error))
      this.stop()
    }, 180000)

    child.stdout?.setEncoding("utf8")
    child.stdout?.on("data", (chunk: string) => this.onStdout(chunk, timer))

    child.stderr?.setEncoding("utf8")
    child.stderr?.on("data", (chunk: string) => {
      this.stderr = (this.stderr + chunk).slice(-3000)
    })

    child.on("error", (error) => {
      clearTimeout(timer)
      this.status.error = error.message
      this.readyReject?.(error)
      this.failWaiters(error)
    })

    child.on("close", (code) => {
      clearTimeout(timer)
      const detail = this.stderr.trim()

      if (!this.status.ready) {
        this.status = {
          ready: false,
          model: this.model,
          device: "cuda",
          error: detail || `Whisper worker exited with code ${code ?? "unknown"}`,
        }
        this.readyReject?.(new Error(this.status.error))
      } else {
        this.status = {
          ready: false,
          model: this.model,
          device: "cuda",
          error: detail || `Whisper worker exited with code ${code ?? "unknown"}`,
        }
      }

      this.failWaiters(new Error(this.status.error || "Whisper worker stopped"))
      this.child = undefined
      this.readyPromise = undefined
    })

    return this.readyPromise
  }

  private onStdout(chunk: string, timer: NodeJS.Timeout) {
    this.buffer += chunk

    let index = this.buffer.indexOf("\n")
    while (index >= 0) {
      const line = this.buffer.slice(0, index).trim()
      this.buffer = this.buffer.slice(index + 1)

      if (line) {
        try {
          const event = JSON.parse(line) as {
            type?: string
            id?: string
            text?: string
            language?: string
            model?: string
            detail?: string
          }

          if (event.type === "ready") {
            clearTimeout(timer)
            this.status = {
              ready: true,
              model: event.model ?? this.model,
              device: "cuda",
              error: "",
            }
            this.readyResolve?.()
          } else if (event.type === "result" && event.id) {
            const waiter = this.waiters.get(event.id)
            if (waiter) {
              clearTimeout(waiter.timer)
              this.waiters.delete(event.id)
              waiter.resolve({ text: event.text ?? "", language: event.language ?? "" })
            }
          } else if (event.type === "error") {
            const error = new Error(event.detail || "Whisper failed")
            if (event.id) {
              const waiter = this.waiters.get(event.id)
              if (waiter) {
                clearTimeout(waiter.timer)
                this.waiters.delete(event.id)
                waiter.reject(error)
              }
            } else {
              this.status.error = error.message
              this.readyReject?.(error)
            }
          }
        } catch {
          // Ignore non-JSON output such as warnings.
        }
      }

      index = this.buffer.indexOf("\n")
    }
  }

  private failWaiters(error: Error) {
    for (const waiter of this.waiters.values()) {
      clearTimeout(waiter.timer)
      waiter.reject(error)
    }
    this.waiters.clear()
  }

  async transcribe(input: WhisperInput): Promise<WhisperResult> {
    if (!this.child || !this.readyPromise || !this.status.ready) {
      await this.start(input.python || DEFAULT_PYTHON, input.model || "large-v3-turbo")
    }
    await this.readyPromise

    const dir = join(tmpdir(), "opencode-voice-dictation")
    mkdirSync(dir, { recursive: true })
    const extension = input.mime.includes("webm") ? "webm" : "wav"
    const file = join(dir, `whisper-${randomUUID()}.${extension}`)
    writeFileSync(file, Buffer.from(input.audio, "base64"))

    const id = randomUUID()
    const path = toWslPath(file)

    try {
      return await new Promise<WhisperResult>((resolve, reject) => {
        const timer = setTimeout(() => {
          this.waiters.delete(id)
          reject(new Error("Whisper transcription timed out"))
        }, 120000)

        this.waiters.set(id, { resolve, reject, timer })
        this.child?.stdin?.write(`${JSON.stringify({ id, path, language: input.language })}\n`)
      })
    } finally {
      try {
        rmSync(file, { force: true })
      } catch {
        // Best effort.
      }
    }
  }

  async warm(python: string, model: string): Promise<WhisperStatus> {
    if (!this.status.ready) {
      await this.start(python || DEFAULT_PYTHON, model || "large-v3-turbo")
    }
    return this.statusOf()
  }

  statusOf(): WhisperStatus {
    return { ...this.status }
  }

  stop() {
    this.failWaiters(new Error("Whisper worker stopped"))
    if (this.child) {
      const child = this.child
      this.child = undefined
      this.readyPromise = undefined
      child.kill()
      if (process.platform === "win32" && child.pid) {
        spawn("taskkill", ["/PID", String(child.pid), "/T", "/F"], { windowsHide: true, stdio: "ignore" })
      }
    }
  }
}

import { spawn, type ChildProcess } from "node:child_process"
import { randomUUID } from "node:crypto"
import { accessSync, chmodSync, constants, existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs"
import { connect } from "node:net"
import { homedir, tmpdir } from "node:os"
import { join } from "node:path"

const RELEASE = "v1.9.2"
const X64_TARBALL = `https://github.com/ggml-org/whisper.cpp/releases/download/${RELEASE}/whisper-bin-ubuntu-x64.tar.gz`
const ARM64_TARBALL = `https://github.com/ggml-org/whisper.cpp/releases/download/${RELEASE}/whisper-bin-ubuntu-arm64.tar.gz`
const MODEL_BASE = "https://huggingface.co/ggerganov/whisper.cpp/resolve/main"

const MODELS = {
  "base-q5_1": "ggml-base-q5_1.bin",
  "small-q5_1": "ggml-small-q5_1.bin",
} as const

type ModelKey = keyof typeof MODELS

export interface WhisperCppStatus {
  installed: boolean
  ready: boolean
  model: string
  error: string
  ffmpeg: boolean
  ffmpegVersion: string
  ffmpegPath: string
}

export interface WhisperCppResult {
  text: string
  language: string
}

export interface FfmpegStatus {
  available: boolean
  version: string
  path: string
  error: string
}

export interface InstallFfmpegResult {
  ok: boolean
  error: string
  command: string
}

interface RunResult {
  code: number | null
  stdout: string
  stderr: string
}

function rootDir(): string {
  return join(homedir(), ".local", "share", "opencode-voice-dictation", "whisper.cpp")
}

function packageDir(): string {
  return join(rootDir(), process.arch === "arm64" ? "whisper-bin-ubuntu-arm64" : "whisper-bin-ubuntu-x64")
}

function binaryPath(): string {
  return join(packageDir(), "whisper-server")
}

function modelFile(model: string): ModelKey {
  return model in MODELS ? (model as ModelKey) : "base-q5_1"
}

function modelPath(model: string): string {
  return join(rootDir(), MODELS[modelFile(model)])
}

async function download(url: string, destination: string): Promise<void> {
  const response = await fetch(url)

  if (!response.ok) {
    throw new Error(`Download failed (${response.status}): ${url}`)
  }

  mkdirSync(rootDir(), { recursive: true })
  writeFileSync(destination, Buffer.from(await response.arrayBuffer()))
}

function run(command: string, args: string[]): Promise<string> {
  return new Promise((resolve, reject) => {
    const child = spawn(command, args, { windowsHide: true })
    let stderr = ""

    child.stderr?.setEncoding("utf8")
    child.stderr?.on("data", (chunk: string) => {
      stderr = (stderr + chunk).slice(-2000)
    })

    child.on("error", reject)
    child.on("close", (code) => {
      if (code === 0) resolve(stderr)
      else reject(new Error(stderr.trim() || `${command} exited with code ${code ?? "unknown"}`))
    })
  })
}

/** Runs a command and returns its output instead of throwing on a non-zero exit. */
function runCapture(command: string, args: string[]): Promise<RunResult> {
  return new Promise((resolve) => {
    const child = spawn(command, args, { windowsHide: true })
    let stdout = ""
    let stderr = ""

    child.stdout?.setEncoding("utf8")
    child.stdout?.on("data", (chunk: string) => {
      stdout = (stdout + chunk).slice(-8000)
    })
    child.stderr?.setEncoding("utf8")
    child.stderr?.on("data", (chunk: string) => {
      stderr = (stderr + chunk).slice(-8000)
    })

    child.on("error", (cause) => {
      resolve({ code: null, stdout, stderr: (stderr + errorText(cause)).slice(-8000) })
    })
    child.on("close", (code) => {
      resolve({ code, stdout, stderr: stderr.slice(-8000) })
    })
  })
}

function errorText(cause: unknown): string {
  return cause instanceof Error ? cause.message : String(cause)
}

function commandExists(command: string): boolean {
  const path = process.env.PATH ?? ""

  return path.split(":").some((directory) => {
    try {
      accessSync(join(directory || ".", command), constants.X_OK)
      return true
    } catch {
      return false
    }
  })
}

/** Checks that ffmpeg can run. ffmpeg converts the browser WebM to 16 kHz WAV. */
export async function detectFfmpeg(): Promise<FfmpegStatus> {
  const result = await runCapture("ffmpeg", ["-version"])

  if (result.code === 0) {
    const version =
      result.stdout
        .split(/\r?\n/)
        .map((line) => line.trim())
        .find((line) => line.startsWith("ffmpeg version")) ?? "ffmpeg"

    return { available: true, version, path: "ffmpeg", error: "" }
  }

  return {
    available: false,
    version: "",
    path: "",
    error: result.stderr.trim() || "ffmpeg not found in PATH",
  }
}

/**
 * Installs ffmpeg with the system package manager.
 *
 * Uses `pkexec` (the desktop's authentication dialog) so the user's password is
 * never handled by the plugin. Falls back to passwordless `sudo -n` and, if
 * neither works, returns the command the user can run manually.
 */
export async function installFfmpeg(): Promise<InstallFfmpegResult> {
  const manual = "sudo apt update && sudo apt install -y ffmpeg"

  if (process.platform !== "linux") {
    return { ok: false, error: "Automatic ffmpeg installation is only available on Linux", command: manual }
  }

  const current = await detectFfmpeg()
  if (current.available) {
    return { ok: true, error: "", command: "" }
  }

  if (!commandExists("apt-get")) {
    const command = commandExists("dnf")
      ? "sudo dnf install -y ffmpeg"
      : commandExists("pacman")
        ? "sudo pacman -S --noconfirm ffmpeg"
        : commandExists("zypper")
          ? "sudo zypper install -y ffmpeg"
          : manual

    return { ok: false, error: "No supported package manager was found", command }
  }

  const install = "DEBIAN_FRONTEND=noninteractive apt-get install -y ffmpeg"
  const updateAndInstall = `DEBIAN_FRONTEND=noninteractive apt-get update && ${install}`
  const attempts: Array<{ command: string; args: string[] }> = []

  if (commandExists("pkexec")) {
    attempts.push({ command: "pkexec", args: ["sh", "-c", install] })
    attempts.push({ command: "pkexec", args: ["sh", "-c", updateAndInstall] })
  }

  if (commandExists("sudo")) {
    attempts.push({ command: "sudo", args: ["-n", "sh", "-c", install] })
    attempts.push({ command: "sudo", args: ["-n", "sh", "-c", updateAndInstall] })
  }

  let lastError = ""

  for (const attempt of attempts) {
    const result = await runCapture(attempt.command, attempt.args)

    if (result.code === 0) {
      const after = await detectFfmpeg()
      if (after.available) return { ok: true, error: "", command: "" }
      lastError = after.error || "ffmpeg is still not available"
      continue
    }

    lastError = result.stderr.trim() || `${attempt.command} exited with code ${result.code ?? "unknown"}`

    // 126 is "dismissed/not authorized" in pkexec: do not ask for the password
    // again just because the update-and-install fallback exists.
    if (attempt.command === "pkexec" && (result.code === 126 || result.code === 127)) break
  }

  return {
    ok: false,
    error: lastError || "ffmpeg installation failed",
    command: manual,
  }
}

export async function installWhisperCpp(model: string): Promise<{ ok: boolean; model: string; error: string }> {
  if (process.platform !== "linux") {
    return { ok: false, model: modelFile(model), error: "Whisper.cpp native is only implemented for Linux" }
  }

  try {
    mkdirSync(rootDir(), { recursive: true })

    if (!existsSync(binaryPath())) {
      const tarball = join(rootDir(), "whisper-bin.tar.gz")
      await download(process.arch === "arm64" ? ARM64_TARBALL : X64_TARBALL, tarball)
      await run("tar", ["-xzf", tarball, "-C", rootDir()])
      rmSync(tarball, { force: true })
      chmodSync(binaryPath(), 0o755)
    }

    const file = modelFile(model)
    if (!existsSync(modelPath(file))) {
      await download(`${MODEL_BASE}/${MODELS[file]}`, modelPath(file))
    }

    return { ok: true, model: file, error: "" }
  } catch (cause) {
    return { ok: false, model: modelFile(model), error: cause instanceof Error ? cause.message : String(cause) }
  }
}

interface StartState {
  child: ChildProcess
  port: number
  model: string
  language: string
  stderr: string
}

export class WhisperCppEngine {
  private state: StartState | undefined
  private starting: Promise<number> | undefined
  private error = ""

  private waitForPort(port: number, timeout: number): Promise<number> {
    const started = Date.now()

    return new Promise((resolve, reject) => {
      const attempt = () => {
        const socket = connect(port, "127.0.0.1")

        socket.once("connect", () => {
          socket.destroy()
          resolve(port)
        })

        socket.once("error", () => {
          socket.destroy()
          if (Date.now() - started > timeout) {
            reject(new Error("whisper-server did not start in time"))
            return
          }
          setTimeout(attempt, 250)
        })
      }

      attempt()
    })
  }

  private async ensure(model: string, language: string): Promise<number> {
    const file = modelFile(model)
    const lang = language || "auto"

    if (this.state && this.state.model === file && this.state.language === lang) {
      return this.state.port
    }

    if (this.starting) return this.starting

    this.stop()
    this.error = ""

    for (const path of [binaryPath(), modelPath(file)]) {
      if (!existsSync(path)) {
        throw new Error("Whisper.cpp is not installed. Open Settings and download it first.")
      }
    }

    const port = 18081 + Math.floor(Math.random() * 500)
    const child = spawn(
      binaryPath(),
      ["-m", modelPath(file), "-l", lang, "-t", "4", "--host", "127.0.0.1", "--port", String(port)],
      {
        cwd: packageDir(),
        env: {
          ...process.env,
          LD_LIBRARY_PATH: [packageDir(), process.env.LD_LIBRARY_PATH].filter(Boolean).join(":"),
        },
        windowsHide: true,
        stdio: ["ignore", "ignore", "pipe"],
      },
    )

    const state: StartState = { child, port, model: file, language: lang, stderr: "" }
    this.state = state

    child.stderr?.setEncoding("utf8")
    child.stderr?.on("data", (chunk: string) => {
      state.stderr = (state.stderr + chunk).slice(-2000)
    })

    const exited = new Promise<never>((_, reject) => {
      child.once("error", (cause) => reject(cause))
      child.once("close", (code) => {
        if (this.state === state) this.state = undefined
        reject(new Error(state.stderr.trim() || `whisper-server exited with code ${code ?? "unknown"}`))
      })
    })
    exited.catch(() => {})

    this.starting = Promise.race([this.waitForPort(port, 120000), exited])
      .then((value) => {
        this.starting = undefined
        return value
      })
      .catch((cause) => {
        this.starting = undefined
        this.error = cause instanceof Error ? cause.message : String(cause)
        this.stop()
        throw cause
      })

    return this.starting
  }

  async transcribe(input: {
    audio: string
    mime: string
    language: string
    model: string
  }): Promise<WhisperCppResult> {
    const ffmpeg = await detectFfmpeg()

    if (!ffmpeg.available) {
      throw new Error(
        `FFMPEG_MISSING: ffmpeg is required to convert the audio. Install it with: sudo apt install -y ffmpeg (${ffmpeg.error})`,
      )
    }

    const port = await this.ensure(input.model, input.language)

    const dir = join(tmpdir(), "opencode-voice-dictation")
    mkdirSync(dir, { recursive: true })

    const extension = input.mime.includes("webm") ? "webm" : "wav"
    const source = join(dir, `whispercpp-${randomUUID()}.${extension}`)
    const wav = `${source}.wav`

    writeFileSync(source, Buffer.from(input.audio, "base64"))

    try {
      try {
        await run("ffmpeg", [
          "-y",
          "-loglevel",
          "error",
          "-i",
          source,
          "-ar",
          "16000",
          "-ac",
          "1",
          "-c:a",
          "pcm_s16le",
          wav,
        ])
      } catch (cause) {
        throw new Error(`ffmpeg failed: ${errorText(cause)}`)
      }

      const form = new FormData()
      form.append("file", new Blob([new Uint8Array(readFileSync(wav))], { type: "audio/wav" }), "audio.wav")

      const response = await fetch(`http://127.0.0.1:${port}/inference`, { method: "POST", body: form })

      if (!response.ok) {
        throw new Error(`whisper-server HTTP ${response.status}`)
      }

      const data = (await response.json()) as { text?: string }

      return {
        text: (data.text ?? "").trim(),
        language: input.language || "",
      }
    } finally {
      rmSync(source, { force: true })
      rmSync(wav, { force: true })
    }
  }

  async status(model: string): Promise<WhisperCppStatus> {
    const file = modelFile(model)
    const ffmpeg = await detectFfmpeg()
    const installed = existsSync(binaryPath()) && existsSync(modelPath(file))

    return {
      installed,
      ready: this.state !== undefined && this.state.model === file,
      model: file,
      error: this.error,
      ffmpeg: ffmpeg.available,
      ffmpegVersion: ffmpeg.version,
      ffmpegPath: ffmpeg.path,
    }
  }

  stop() {
    if (this.state) {
      const child = this.state.child
      this.state = undefined
      child.kill()
      if (child.pid) {
        spawn("pkill", ["-P", String(child.pid)], { windowsHide: true, stdio: "ignore" })
      }
    }
    this.starting = undefined
  }
}
